insert into public.source_items (id, dealer_id, provider, external_id, source_url, raw, text_hash, content_hash, available, publish, extracted, extracted_hash, applied_hash, photos_hash, error, listing_id, first_seen_at, last_seen_at) values
  ('ac488af5-1ab4-43ee-b5b7-194de6f1ac75', 'ad0d7d71-741a-4b65-9465-641ed9cc0199', 'squarespace', 'squarespace:67d45166ab754663f48c95aa', 'https://goldfingersvintage.com/watches/p/1980s-corum-skeleton-dress-watch-factory-diamond-18k-wg', '{"meta":{"sku":"GVW207","vendor":null,"updatedAt":"2026-08-29T00:05:57.845Z","photoCount":7,"productType":null,"publishedAt":"2025-03-14T15:58:02.109Z"},"text":"A spectacular 1980s Corum Skeletonized Dress Watch in 18K white gold, with a beautiful chapter ring factory set with diamonds, hand engraved bridges and stunningly organized architecture based on the Audemars Piguet caliber 2003. \nThe case measures a charming 30mm, 32mm with crown and 38mm lug to lug. \nComes with its original steel Corum buckle. \nThe manual wind caliber is running well.","title":"1980''s Corum Skeleton Dress Watch Factory Diamond 18K WG","currency":"USD","available":true,"photoUrls":["https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/6ed0355b-7a31-499e-9fd5-7156c2b40988/DSC03967.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/6a432e39-a505-4fc0-86d6-671cbbcf7ea6/DSC03982.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/5f4563eb-96d8-4683-a96c-b7ac241575b2/DSC03994.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/90c0f315-79f8-4387-8b18-635de973632c/DSC04007.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/e321a951-0a35-4665-93ba-c3ea772b554c/DSC04021.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/255348ba-60b3-40ad-956e-580ed0ec9027/DSC04034.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/c91ea3ec-f1b2-4be7-8a77-6b65a38598ec/DSC04037.jpg?format=1500w"],"sourceUrl":"https://goldfingersvintage.com/watches/p/1980s-corum-skeleton-dress-watch-factory-diamond-18k-wg","externalId":"squarespace:67d45166ab754663f48c95aa","priceCents":1099500}'::jsonb, '84fb91c031e98717b3162b24b07fc971f67d185fa8fc08564013a3fd8f583a23', 'b8667e0935bb95f5e882fd6544ee786e410a43055aed124f42c39d4e4344fc6b', true, true, '{"year":1980,"brand":"Corum","model":"Skeleton","style":"dress","caliber":"Cal. 2003","has_box":null,"winding":"manual","currency":"USD","brand_key":"corum","condition":null,"reference":null,"dial_color":null,"has_papers":null,"description":"This is a 1980s Corum Skeletonized Dress Watch in 18K white gold, featuring a chapter ring factory set with diamonds and hand engraved bridges.","price_cents":1099500,"case_size_mm":30,"case_material":"white_gold","complications":[]}'::jsonb, '84fb91c031e98717b3162b24b07fc971f67d185fa8fc08564013a3fd8f583a23', 'b8667e0935bb95f5e882fd6544ee786e410a43055aed124f42c39d4e4344fc6b', '16378cddb596d4f14e9907f56754620585271d312d5e942fb2d2de1b766e95d2', null, 'e222bf87-9c59-49ab-8547-962db5116442', '2026-09-14T15:48:12.101559+00:00', '2026-09-22T01:08:52.208+00:00'),
  ('70ca596c-cb26-4d29-a7be-25eeb81d4585', 'ad0d7d71-741a-4b65-9465-641ed9cc0199', 'squarespace', 'squarespace:68f69a35947a864d0948aa38', 'https://goldfingersvintage.com/watches/p/1960s-eberhard-scafograf-300-diver-ref-26013', '{"meta":{"sku":"GVW346","vendor":null,"updatedAt":"2026-08-30T13:44:55.713Z","photoCount":12,"productType":null,"publishedAt":"2025-10-20T20:24:52.395Z"},"text":"A rugged and amazing example of the Eberhard Scafograf 300 Diver ref. 26013 from the 1960s, with a very sharp 42mm case featuring signature brushed and beveled twisted lugs, flat satin brushed mid case, and a glossy black dial with beautifully aged and matching lume, and powered by the automatic Eberhard caliber 250-123. \nBeyond the Submariner, Omega Diver 300, Blancpain and countless others, the Eberhard Scafograf 300 was the diver of choice for the ones who went against the grain. With unidirectional rotating aluminum bezel, glossy black dial, this purpose built tool watch shows its age and use with grace, having never been polished; each ding shows a life lived with respect which what a watch like this should look like after 65 years. \nWhat’s more this comes paired on an Eberhard signed Unroc buckle. Keeping time and running well. We do not have service history.","title":"1960''s Eberhard Scafograf 300 Diver ref. 26013","currency":"USD","available":true,"photoUrls":["https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/29a44863-8f34-4dcf-b974-15e1e6c4c098/DSC00998.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/ffb0a29a-d089-49fc-8a6e-8d831d28762f/DSC01016.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/05b22077-11d5-4058-b9c4-ff9582df1a32/DSC01006.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/a6162df1-8f15-4e2c-b022-e4c95582c3db/DSC01027.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/c989a5f7-77c9-47a7-bfba-e1ba54d5bc91/DSC01034.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/72544a60-3cb8-434f-9237-6bc09dbc8735/DSC01054.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/859fa01e-c22a-4cb4-a544-5408237689fc/DSC01060.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/f2261d2d-d735-4f9c-bb57-eda5eb2408b9/DSC01065.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/d29aeda3-30cc-4c28-83b1-96efe3030464/DSC01073.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/4b91261c-290d-4a7a-b17d-ee6b51d2dbdb/DSC01078.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/5a74b8cd-7415-419a-878e-664c9a7fc0cb/DSC01083.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/97f6a82f-ced2-4539-9a5e-759a7a5a040c/DSC01091.jpg?format=1500w"],"sourceUrl":"https://goldfingersvintage.com/watches/p/1960s-eberhard-scafograf-300-diver-ref-26013","externalId":"squarespace:68f69a35947a864d0948aa38","priceCents":519500}'::jsonb, 'b261fa42d18f1e9fef60e5035286602448ee6ba4d6cbc09d2d03ad3c586afe76', 'ad6cab0818422816aa50223f7d7d92f323e76d5fc38869e600cefecc6a4a2f7d', true, true, '{"year":1960,"brand":"Eberhard","model":"Scafograf 300 Diver","style":"diver","caliber":"Eberhard caliber 250-123","has_box":null,"winding":"automatic","currency":"USD","brand_key":"eberhard","condition":null,"reference":"26013","dial_color":"black","has_papers":null,"description":"This is a rugged example of the Eberhard Scafograf 300 Diver ref. 26013 from the 1960s, featuring a glossy black dial and powered by the automatic Eberhard caliber 250-123. The watch shows its age and use with grace and has never been polished.","price_cents":519500,"case_size_mm":42,"case_material":null,"complications":[]}'::jsonb, 'b261fa42d18f1e9fef60e5035286602448ee6ba4d6cbc09d2d03ad3c586afe76', 'ad6cab0818422816aa50223f7d7d92f323e76d5fc38869e600cefecc6a4a2f7d', '97b96c2d8a696de4c1a6a4c9fbb447e8bc1fae1f72479e541b11e0c158a34ca3', null, 'b65986de-43e8-4541-903f-d8905672e5b4', '2026-09-14T15:48:12.018814+00:00', '2026-09-22T01:08:52.208+00:00'),
  ('bb887cbf-b51e-4c26-b35d-9c008300a912', 'ad0d7d71-741a-4b65-9465-641ed9cc0199', 'squarespace', 'squarespace:6a66e8caee0be167547500c5', 'https://goldfingersvintage.com/watches/p/1930s-patek-philippe-sector-dial-tank-carr-pre-reference', '{"meta":{"sku":"GVW549","vendor":null,"updatedAt":"2026-09-01T08:10:30.882Z","photoCount":10,"productType":null,"publishedAt":"2026-07-27T05:14:37.400Z"},"text":"An incredible 1930s Patek Philippe pre-reference Tank Carr&eacute; with a gorgeous sector dial in phenomenal condition, its hand carved enamel dial with stunning relief and clarity present after nearly a century of life, its 26x26mm case sharp and patinated, with convex sloped top and bottom bezels defining its edges at crimped corners, powered by an early LeCoultre based, Patek signed caliber that is keeping accurate time. \nWe have just filed for its Patek Philippe Extract from the Archives.","title":"1930''s Patek Philippe Sector Dial Tank Carré Pre-Reference","currency":"USD","available":true,"photoUrls":["https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/4749b1b0-a245-45df-9f47-482bd59e5540/B0004457.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/505492f0-c47d-4b69-a735-330a1c004b9f/B0004471.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/7e14aca3-0e1e-4fac-9e28-a560cdc6febf/B0004495.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/c9167a0a-fdec-4606-a9e4-d62124b963ad/B0004524.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/406ae9d9-3881-498c-96f0-13c00e9912af/B0004508.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/82ae94c0-c899-4a82-95e2-a571e8de12e4/B0004505.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/bf901352-a897-494d-ac1c-364467e00ce5/B0004503.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/990fbe5a-dc3d-4903-9025-99cc82bf118c/B0004501.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/2180b2a2-55cc-4d3f-a281-92899c174e66/B0004488.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/206de269-4246-45c7-a8fc-e6bbab4678dc/B0004482.jpg?format=1500w"],"sourceUrl":"https://goldfingersvintage.com/watches/p/1930s-patek-philippe-sector-dial-tank-carr-pre-reference","externalId":"squarespace:6a66e8caee0be167547500c5","priceCents":3999500}'::jsonb, '57b4df8b39f0528398d14a127dcbb14d664a7b40ee28ee517f92740c018ecd9a', 'bb0215fef98ab263cee2bf111a2cd7b5fad1332097a14407968555471350497d', true, true, '{"year":1930,"brand":"Patek Philippe","model":"Tank Carré","style":"dress","caliber":"LeCoultre based","has_box":null,"winding":null,"currency":"USD","brand_key":"patekphilippe","condition":null,"reference":null,"dial_color":null,"has_papers":null,"description":"This 1930s Patek Philippe pre-reference Tank Carré features a gorgeous sector dial and is powered by an early LeCoultre based movement. The watch''s 26x26mm case is sharp and patinated, with convex sloped bezels.","price_cents":3999500,"case_size_mm":26,"case_material":"other","complications":[]}'::jsonb, '57b4df8b39f0528398d14a127dcbb14d664a7b40ee28ee517f92740c018ecd9a', 'bb0215fef98ab263cee2bf111a2cd7b5fad1332097a14407968555471350497d', 'b50a57cd19c625bca86a21242781a4561ac1f7888ef8da2f536473e8db6d9ee0', null, 'b18e26ab-5c84-4089-bdf9-7f75dc4fa724', '2026-09-14T15:48:11.878242+00:00', '2026-09-22T01:08:52.208+00:00'),
  ('33a613d6-dfb8-4755-a44b-a8b13e5e67b9', 'ad0d7d71-741a-4b65-9465-641ed9cc0199', 'squarespace', 'squarespace:6a6fa5a68d7a8a3a29137d8f', 'https://goldfingersvintage.com/watches/p/1960s-movado-bull-horn-dress-watch-ref-5036-18k-yg', '{"meta":{"sku":"GVW543","vendor":null,"updatedAt":"2026-09-01T09:16:41.071Z","photoCount":6,"productType":null,"publishedAt":"2026-08-02T20:18:43.296Z"},"text":"A super cool and rare 1960s Movado ref. 5306 dress watch in a Wenger crafted 18K yellow gold case with fancy “Bull Horn” lugs and a textured art deco bezel with stick indexes and minimalist champagne dial, measuring a pleasing 33mm x 24mm, powered by the manually wound Movado caliber 1156 which is running well and keeping accurate time.","title":"1960''s Movado \"Bull Horn\" Dress Watch ref. 5036 18K YG","currency":"USD","available":true,"photoUrls":["https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/7f07aa06-7645-4d51-a482-45de2eaa7ec7/B0004879.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/866e4152-a3d5-40d3-8570-5253ca030633/B0004892.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/e092a566-78dc-45bf-b66c-1f82f0a8b0ae/B0004921.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/a19a954d-aa3a-458e-a17d-ea87cd1d2a2d/B0004909.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/1147c7cd-280f-42ff-a01d-9ddc3d12f1e1/B0004934.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/b08e5918-c621-4412-ae0d-aac099f3cf5b/B0004895.jpg?format=1500w"],"sourceUrl":"https://goldfingersvintage.com/watches/p/1960s-movado-bull-horn-dress-watch-ref-5036-18k-yg","externalId":"squarespace:6a6fa5a68d7a8a3a29137d8f","priceCents":539500}'::jsonb, 'a522348e42fc9e74ed44e538bd29df868433f28fa1b72206f3b9fe57e923f14d', '383025fb76c88a0d02a540c87f2bae8fb34af3cc9b48bed972696484af7949b4', true, true, '{"year":1960,"brand":"Movado","model":"Bull Horn","style":"dress","caliber":"Cal. 1156","has_box":null,"winding":"manual","currency":"USD","brand_key":"movado","condition":null,"reference":"5036","dial_color":"champagne","has_papers":null,"description":"This is a rare 1960s Movado dress watch with a unique ''Bull Horn'' design and a textured art deco bezel. It features a minimalist champagne dial and is powered by a manually wound Movado caliber 1156.","price_cents":539500,"case_size_mm":33,"case_material":"yellow_gold","complications":[]}'::jsonb, 'a522348e42fc9e74ed44e538bd29df868433f28fa1b72206f3b9fe57e923f14d', '383025fb76c88a0d02a540c87f2bae8fb34af3cc9b48bed972696484af7949b4', '27e6cea504ddf2f9598cc71b48023db1582569c107fb908aa100c4bd347fb383', null, 'daf45b0f-2556-4318-9ebb-912452c8f847', '2026-09-14T15:48:11.878242+00:00', '2026-09-22T01:08:52.208+00:00'),
  ('09d968db-c2aa-4fc1-9bfa-eac99d93fccb', 'ad0d7d71-741a-4b65-9465-641ed9cc0199', 'squarespace', 'squarespace:6a5531bbd0719241db24e00f', 'https://goldfingersvintage.com/watches/p/1940s-cartier-grande-normale-w-ewc-movement-extremely-rare', '{"meta":{"sku":"GVW537","vendor":null,"updatedAt":"2026-09-01T06:10:30.149Z","photoCount":12,"productType":null,"publishedAt":"2026-07-13T18:49:37.424Z"},"text":"An incredibly special and very rare 1940s Cartier Grande Normale, a larger take on the classic standard size, it’s Edmond Jaeger crafted case measuring in at a proud 32x24mm with 19mm lugs, likely unpolished with sharp hallmarks and wide bevels still very present, its pad printed dial bears unmistakable and characteristic aging left to time and not disturbed by interference, paired on its period correct French made deployant, powered by a manually wound EWC movement. \nThis is a Cartier fit for the most astute collector, for one looking for the unattainable. For comparison, the standard ref. 7809 Normale measures about 30 × 23mm while the additional few millimeters on this larger case really increase the wearing experience noticeably. Its dial is completely original with amazing pad printing across its entire surface with only slight chipping around some of its edges. For a Cartier this old, its humbling to find an example this rare without any evidence of restoration. \n Its EWC signed caliber is running well and keeping accurate time. We do not have service history.","title":"1940''s Cartier Grande Normale w/ EWC Movement *Extremely Rare*","currency":"USD","available":true,"photoUrls":["https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/be35b0d1-adac-410e-bffd-aad09add4a10/B0002733.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/df4453e3-d989-4404-ab9a-107baef590c4/B0002733.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/23279f13-13c6-49d2-bf76-0cb07bc02048/B0002811.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/877b8288-fec5-496a-a319-1f0275d282f2/B0002740.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/7ef4eaf7-6c4c-491d-bdeb-2afb2653ab40/B0002807.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/84897144-5fd1-4981-8f74-e90da861d216/B0002805.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/e7fc4727-f931-4977-a06f-e693dee83c9d/B0002803.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/54a7e08b-247d-4022-ae94-bc2a5ed2218d/B0002800.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/0d1edbe8-684c-4b0c-b67c-f6e34173cdb5/B0002797.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/a95bfd69-dedb-48d5-ba69-cd17302cb820/B0002793.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/729925da-ec83-49d4-b680-e01a90e8ccd5/B0002783.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/60c87d2c-5e30-48c8-8cb8-c1b225e99da7/B0002760.jpg?format=1500w"],"sourceUrl":"https://goldfingersvintage.com/watches/p/1940s-cartier-grande-normale-w-ewc-movement-extremely-rare","externalId":"squarespace:6a5531bbd0719241db24e00f","priceCents":7150000}'::jsonb, 'e0384aae7f9a617b087d8ae0281ce34730db2acb8eba6715ae8f5af9458721ee', 'ff05e3ad68769394dd41fb672035dd5750a3560d252d1e30c5faebb96cc03710', true, true, '{"year":1940,"brand":"Cartier","model":"Grande Normale","style":"dress","caliber":"EWC","has_box":null,"winding":"manual","currency":"USD","brand_key":"cartier","condition":null,"reference":null,"dial_color":null,"has_papers":null,"description":"This is a very rare 1940s Cartier Grande Normale with a larger case measuring 32x24mm, powered by a manually wound EWC movement. The original dial shows characteristic aging and is paired with a period-correct deployant.","price_cents":7150000,"case_size_mm":32,"case_material":"other","complications":[]}'::jsonb, 'e0384aae7f9a617b087d8ae0281ce34730db2acb8eba6715ae8f5af9458721ee', 'ff05e3ad68769394dd41fb672035dd5750a3560d252d1e30c5faebb96cc03710', '4e1c5aff1736efc1770b53bc61537330979bfcbb4a36061cbac3668a761c71c0', null, '57480b37-a412-498f-96ca-97b41e15df1a', '2026-09-14T15:48:11.878242+00:00', '2026-09-22T01:08:52.208+00:00'),
  ('f7d9fba6-38f6-401e-bdb8-ffdc2df1067f', 'ad0d7d71-741a-4b65-9465-641ed9cc0199', 'squarespace', 'squarespace:6a4fe3f94c53b157280f179b', 'https://goldfingersvintage.com/watches/p/1980s-audemars-piguet-quantieme-perpetual-pocket-watch-ref-5555ba', '{"meta":{"sku":"GVW533","vendor":null,"updatedAt":"2026-09-01T05:38:05.615Z","photoCount":9,"productType":null,"publishedAt":"2026-07-09T18:14:36.146Z"},"text":"A marvelous 1980s Audemars Piguet Quantieme Perpetual Pocket Watch ref. 5555BA in a heavy stepped 45mm solid 18K yellow gold case, with a lacquered white dial which appears almost porcelain-esque, with Roman numerals, day, date, month, Moonphase and leap year complication, powered by the meticulously finished AP cal. 5020/2820. \nAccording to the AP Chronicles, only 200 of these calibers were produced with the perpetual calendar module from its introduction in 1982 making this pocket even more scarce than its standard cal. 5020 bearing siblings. \nTo produce a pocket watch, and a complicated one at that, during the throes of the quartz revolution proves that being contrarian can yield rewarding results.","title":"1980''s Audemars Piguet Quantieme Perpetuel Pocket Watch ref. 5555BA","currency":"USD","available":true,"photoUrls":["https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/0489e201-b0d8-4c84-9add-56afedb9069d/B0003448.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/cf099fb3-0ca1-4f19-b679-0254bf199aaa/B0003422.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/739ef97e-d81e-41a3-9965-79679b0f5978/B0003453.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/41345ebc-c286-42ed-af3a-cd280e32bfa2/B0003476.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/e457b06c-250b-44da-abcf-b1b42c39fa04/B0003490.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee1