  ('ec15fc0d-335c-4265-a6f4-552d5db41e4b', 'ad0d7d71-741a-4b65-9465-641ed9cc0199', 'squarespace', 'squarespace:6a67ab2eee0be16754759434', 'https://goldfingersvintage.com/watches/p/1980s-gerald-genta-broad-arrow-dress-watch-18k-yg', '{"meta":{"sku":"SQ6571552","vendor":null,"updatedAt":"2026-09-01T08:16:24.120Z","photoCount":9,"productType":null,"publishedAt":"2026-07-27T19:06:34.318Z"},"text":"A nutty 1980s creation by the maestro Gerald Genta featuring a 30mm solid 18K yellow gold case with ribbed midcase and a killer deeply stepped dial with exaggerated broad arrow hands, set by a sharp pyramid style crown, paired on its original strap and 18K yellow gold signed pin buckle. \nIts Genta signed quartz caliber is running well with a fresh battery.","title":"1980s Gerald Genta Broad Arrow Dress Watch 18K YG","currency":"USD","available":true,"photoUrls":["https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/ff6fbf90-efc7-4140-8f1c-3063d44d704f/B0004541.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/2ac5f695-475e-47d0-911e-4b5a1acaee70/B0004544.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/79aaf5ed-bfa0-4f8f-8281-c37a9ce0ce14/B0004565.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/79d94f4f-8e80-4e9b-824e-e0ae742502c9/B0004574.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/4108006f-b25d-49d3-a1d1-a91e3df6d22d/B0004569.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/d367e62e-eeec-4858-a64e-3d42d3256a4a/B0004567.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/c7c825e6-e109-4356-ba7b-3f99f5c61337/B0004561.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/ab50d69a-2901-4872-b683-044575b5de01/B0004558.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/