  ('00aeaec7-9cb8-48d9-aef9-91df9fd9f16f', 'ad0d7d71-741a-4b65-9465-641ed9cc0199', 'squarespace', 'squarespace:69fb8f7caaf20800e4a4256e', 'https://goldfingersvintage.com/watches/p/1950s-boucheron-carr-18k-yg-blue-enamel', '{"meta":{"sku":"GVW474","vendor":null,"updatedAt":"2026-08-31T20:15:51.110Z","photoCount":6,"productType":null,"publishedAt":"2026-05-06T19:00:47.342Z"},"text":"A spectacular and very rare 1950s Boucheron Carr&eacute; in a 24mm x24mm solid 18K yellow gold French made case with the French maisons patented sliding strap system, hammered solid gold dial, and hypnotic blue enamel bezel with a checkered motif, all powered by a manually wound Omega caliber. \nIn top condition, this example has seldom been worn. Its movement is running well and keeping accurate time. We do not have service history.","title":"1950''s Boucheron Carré 18K YG & Blue Enamel","currency":"USD","available":true,"photoUrls":["https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/f70dbe5f-7149-452f-8ae6-73519380fa0f/DSC01346.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/a6fe151b-57f0-4393-8edd-d5185272a19f/DSC01359.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/6a7acc6a-224c-4711-9c70-a73ae584f966/DSC01370.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/5d38d4fa-b553-4b3b-b90b-6cb2bc2dfe83/DSC01382.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/b36f4b1e-1dff-40b2-a970-83dd21d475e7/DSC01388.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/19952636-dfc0-42e0-8f96-bdd245f98cb9/DSC01389.jpg?format=1500w"],"sourceUrl":"https://goldfingersvintage.com/watches/p/1950s-boucheron-carr-18k-yg-blue-enamel","externalId":"squarespace:69fb8f7caaf20800e4a4256e","priceCents":1889500}'::jsonb, 'de674d30c4504aa206adb8481bea1ded560e601d1932a3a6bf68928a0718717b', '454965324dd