  ('615badf5-3f4c-4a20-a61d-f88f526a068b', 'ad0d7d71-741a-4b65-9465-641ed9cc0199', 'squarespace', 'squarespace:69d70a1f6892561c57b59a3e', 'https://goldfingersvintage.com/watches/p/ef1x6crmq5q4l2dpl8rucnmej7mo6b', '{"meta":{"sku":"GWW448","vendor":null,"updatedAt":"2026-08-31T15:47:45.555Z","photoCount":9,"productType":null,"publishedAt":"2026-04-09T02:10:56.097Z"},"text":"A rare masterpiece by Audemars Piguet, this important perpetual calendar pocket watch from the 1920s, crafted in a 46mm 18K white gold case, with a hand carved dial with applied breguet numerals, enamel filled dial fixtures including information displayed for day, date, month, phase of the moon and leap year, marks the pinnacle of manufacturing prowess from the maison of this era.","title":"1920’s Audemars Piguet Perpetual Calendar Pocket Watch 18K WG","currency":"USD","available":true,"photoUrls":["https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/1a695ebd-7ce5-4b09-acc7-76063b30e5c8/963C81B0-EBFF-4B32-A388-363F6F474D48.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/1775700543551-TOZLP3W3EQ99G2LR92Q8/2B4913E7-C856-443B-A2A4-FCE021683CA0.jpeg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/1775700541821-LKKDXRPPSK1OSYEWSDCP/811ECCB9-C936-452A-BB0F-020F45247B70.jpeg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/1775700542515-K15UEE32VFDZL706EK2Y/084C6174-6DF7-4FD5-89C4-48965716E1F9.jpeg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/1775700541134-6HU73JUHUSSYTLAXE38D/5522BDBB-BB88-4094-B609-44E60B0C7EB3.jpeg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/1775700641895-M0231NS5JH2STGBYMFYH/EF07F4FC-6DD2-452A-8173-9D236234069B.jpeg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/1775700643855-PVGW0SSCCLM9WIFMIBQU/C1A74960-5BAF-4D4C-A624-243D01869FB9.jpeg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/1775700643239-AJJDWC5J6GIIIF9PL3IS/BAACE209-4C34-4E7E-AAA9-4CADEE6EEFFD.jpeg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/9e5e9748-bcd9-404d-8194-e03011194ca0/DF5EEC06-4C45-46B9-9207-C9B762183DBD.jpg?format=1500w"],"sourceUrl":"https://goldfingersvintage.com/watches/p/ef1x6crmq5q4l2dpl8rucnmej7mo6b","externalId":"squarespace:69d70a1f6892561c57b59a3e","priceCents":4350000}'::jsonb, '35edcad9b0b3615bf96883b8ad601513bc303ace6b95d8b84d7451777045488a', '92bd5d2cde7a70ded9414f9b0595c727e000f412218b4ccd397a26bb4d7d1c84', true, true, '{"year":1920,"brand":"Audemars Piguet","model":"Perpetual Calendar","style":"pocket","caliber":null,"has_box":null,"winding":null,"currency":"USD","brand_key":"audemarspiguet","condition":null,"reference":null,"dial_color":null,"has_papers":null,"description":"This rare masterpiece by Audemars Piguet is a perpetual calendar pocket watch from the 1920s, crafted in an 18K white gold case. It features a hand carved dial with applied Breguet numerals and displays information for day, date, month, phase of the moon, and leap year.","price_cents":4350000,"case_size_mm":46,"case_material":"white_gold","complications":["date","day_date","moonphase","perpetual_calendar"]}'::jsonb, '35edcad9b0b3615bf96883b8ad601513bc303ace6b95d8b84d7451777045488a', '92bd5d2cde7a70ded9414f9b0595c727e000f412218b4ccd397a26bb4d7d1c84', '76bea6da57865ed3c83535bc6979c7391c427116a07078806ecc67fda4d2f2ce', null, 'ae917af7-6719-450e-bdad-c4daa899a6dd', '2026-09-14T15:48:11.951285+00:00', '2026-09-22T01:08:52.208+00:00'),
  ('674f86b5-3c7a-46e3-98f7-e2d4c8dc27e3', 'ad0d7d71-741a-4b65-9465-641ed9cc0199', 'squarespace', 'squarespace:69fa7955f691fe20c13beb6c', 'https://goldfingersvintage.com/watches/p/1940s-jaeger-lecoultre-duo-date-half-sector-two-tone-dial', '{"meta":{"sku":"SQ9919619","vendor":null,"updatedAt":"2026-08-31T20:08:12.812Z","photoCount":8,"productType":null,"publishedAt":"2026-05-05T23:13:54.427Z"},"text":"A wonderful and very rare 1940s Jaeger-LeCoultre Duo Date in a 30mm stainless steel case, that’s seen honest wear yet remains sharp and full of integrity, sporting a rarer still two tone half-sector dial that has retained all of its luster and remains undisturbed by interference, with an Italian day disk, powered by a manually wound JLC caliber that is running well and keeping accurate time. \nThis watch is paired on a period correct Gay Freres ladder style bamboo bracelet, fully adjustable.","title":"1940''s Jaeger-LeCoultre Duo Date Half-Sector Two-Tone Dial","currency":"USD","available":true,"photoUrls":["https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/dc0bb0dd-ba2c-406f-a91f-0f983b618139/DSC01287.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/1e61d545-6e6b-4a06-a576-fdc16b6b96dd/DSC01314.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/15ef69d7-9a0b-4923-ada4-88c9a198b9d6/DSC01295.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/4502cd7f-5436-4c10-a11c-5553601c4f92/DSC01306.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/65f0a1f2-1307-4168-92b5-90b6185b62b1/DSC01329.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/1129013d-0640-4de4-8312-ee3e18df9137/DSC01333.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/4c8ccc45-c20e-428d-87f4-f75ac35070be/DSC01331.jpg?format=1500w","https://images.squarespace-