  ('240ef966-a50a-4b61-b8ef-35e2cfd18983', 'ad0d7d71-741a-4b65-9465-641ed9cc0199', 'squarespace', 'squarespace:69fbdf2e4bf4684fff7e556f', 'https://goldfingersvintage.com/watches/p/1950s-movado-french-market-tempomatic-18k-pg', '{"meta":{"sku":"GVW477","vendor":null,"updatedAt":"2026-08-31T20:19:04.722Z","photoCount":8,"productType":null,"publishedAt":"2026-05-07T00:41:17.494Z"},"text":"A handsome 1950s Movado Tempomatic for the French market, in a 33.5mm unpolished and heavy 18K pink gold French made case, a mint two tone dial with applied pink Arabic numerals, powered by the automatic Movado bumper automatic based caliber 221. \nThe condition of this example is nearly mint and razor sharp. Its caliber is running well and keeping accurate time.","title":"1950''s Movado \"French Market\" Tempomatic 18K PG","currency":"USD","available":true,"photoUrls":["https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/f87c4413-6c7b-49a2-9b57-9b76d0ec4ea9/DSC01403.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/544d3cc6-64bf-4d4b-a0e1-77242617564d/DSC01416.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/4526e720-a9ad-4133-b206-ce0f3dd389cd/DSC01410.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/16deddaa-790c-4321-8cb8-7d782e177bc7/DSC01417.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/6284d79a-84b3-4245-a6ac-74a491bd68dd/DSC01420.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/c795cf1e-1070-4cfc-9054-cff53ad9e6ba/DSC01428.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/35813c1f-6e41-4f34-9978-3e1fefa2bfd3/DSC01442.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/2967a361-6636-4d79-b24f-339a14c8619c/DSC01468.jpg?format=1500w"],"sourceUrl":"https://goldfingersvintage.com/watches/p/1950s-movado-french-market-tempomatic-18k-pg","externalId":"squarespace:69fbdf2e4bf4684fff7e556f","priceCents":699500}'::jsonb, '46e4e3256c86b27b16c08c30070adfc3d659aa8758cdbe665d6a3f9222e6dcee', '12837f6f53a78e687cbb38ee1e94233c842240fc85d8d89180616814c290d772', true, true, '{"year":1950,"brand":"Movado","model":"Tempomatic","style":"other","caliber":"caliber 221","has_box":null,"winding":"automatic","currency":"USD","brand_key":"movado","condition":"nearly mint and razor sharp","reference":null,"dial_color":"other","has_papers":null,"description":"A handsome 1950s Movado Tempomatic for the French market, in a 33.5mm unpolished and heavy 18K pink gold case, with a mint two tone dial.","price_cents":699500,"case_size_mm":33.5,"case_material":"rose_gold","complications":[]}'::jsonb, '46e4e3256c86b27b16c08c30070adfc3d659aa8758cdbe665d6a3f9222e6dcee', '12837f6f53a78e687cbb38ee1e94233c842240fc85d8d89180616814c290d772', 'f8b6d56718e4b388dcdc7b162e46c9b73dc6e1f3097b327ab24876b35b32f772', null, '55e876a1-d45e-4b57-b526-a7d58ab5343f', '2026-09-14T15:48:11.878242+00:00', '2026-09-22T01:08:52.208+00:00'),
  ('181337ed-386e-45c5-9ed3-5a1c8df90048', 'ad0d7d71-741a-4b65-9465-641ed9cc0199', 'squarespace', 'squarespace:6a592426d0719241db2825b0', 'https://goldfingersvintage.com/watches/p/1930s-patek-philippe-two-tone-half-sector-dial-pocket-watch-18k-yg-w-extract', '{"meta":{"sku":"GVW540","vendor":null,"updatedAt":"2026-09-01T06:38:59.835Z","photoCount":9,"productType":null,"publishedAt":"2026-07-16T18:36:33.554Z"},"text":"A marvelous 1930s Patek Philippe Pocket Watch made for the French market, with a silvered two-tone half sector dial with applied Arabic and rectangular indices, it’s champlev&eacute; details immaculately preserved, with subtly raised and hand carved enamel work including its long French signature, circular inner minute track and its outer as well, in a 45mm 18K yellow gold case, powered by a gorgeous Patek caliber which is running well and keeping accurate time. \nThis watch comes with its Extract from the Archives confirming its date of manufacture to 1930 and subsequent sale in 1939. Sold in France as noted by its “Fab Suisse” designation at six o’clock and multiple Owl hallmarks, the French code for imported gold, this magnificent object comes from the days the firm was crafting works of art and retains every iota of beauty that left the manufacturer back in 1930.","title":"1930''s Patek Philippe Two-Tone Half-Sector Dial Pocket Watch 18K YG w/ Extract","currency":"USD","available":true,"photoUrls":["https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/596e15ad-bcd5-49ca-bbd0-7cfa1076e86f/B0003799.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/ee5516d2-0386-4217-9605-b1cabb9972e6/B0003811.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/d7ae9b45-14f3-4c8d-bd2b-2ad9a70ff4f1/B0003863.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/b8e42b6d-2132-45b1-972e-4639731ef9f1/B0003885.jpg?format=1500w","https://images.s