  ('3cee9ed8-fae6-47f4-b408-39e3b4db2d84', 'ad0d7d71-741a-4b65-9465-641ed9cc0199', 'squarespace', 'squarespace:69eff587f5f0215d20f9e72d', 'https://goldfingersvintage.com/watches/p/1950s-jaeger-lecoultre-triple-calendar-ref-2904', '{"meta":{"sku":"GVW461","vendor":null,"updatedAt":"2026-08-31T18:52:41.317Z","photoCount":9,"productType":null,"publishedAt":"2026-04-27T23:49:03.233Z"},"text":"A very handsome and well preserved 1950s Jaeger-LeCoultre Triple Calendar ref. 2904, in a 35mm steel case sporting tear drop lugs, a beautiful dial undisturbed dial with rose applied furnishings, ribbed midcase, a mushroom crown and its correct JLC signed pin buckle, powered by the manually wound JLC caliber 484, which is running well and keeping accurate time.","title":"1950''s Jaeger-LeCoultre Triple Calendar ref. 2904","currency":"USD","available":true,"photoUrls":["https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/c883f4bb-0048-4b91-9e69-b0777f02980d/DSC00602.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/36a07663-3134-4c00-8525-fb0b4313f822/DSC00606.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/b942c1fc-611b-4300-bca6-5b651743b994/DSC00612.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/5877dbd2-c786-40a4-a011-9f8d2985636c/DSC00643.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/79b606cf-879b-4d24-b3f0-bfe0b0674cbf/DSC00646.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/ecf64fd3-d42c-4418-95af-32ca89c789a1/DSC00650.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/963e96af-a021-4d65-a9c2-c322c7a9af0b/DSC00654.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/691d1c1c-480b-4467-8769-12f4fca277cc/DSC00657.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/df54b7ca-8c58-438c-b150-6c4628a09b4b/DSC00659.jpg?format=1500w"],"sourceUrl":"https://goldfingersvintage.com/watches/p/1950s-jaeger-lecoultre-triple-calendar-ref-2904","externalId":"squarespace:69eff587f5f0215d20f9e72d","priceCents":1195000}'::jsonb, '85858b7675a07577fa7562533d2dbe3263117bf5f47ef49da4cb73b7cfd6a6e6', '127127a73fa88c80bdb0e94508f7d824cffea76ad96c52dcd328b5c7b52a1628', true, true, '{"year":1950,"brand":"Jaeger-LeCoultre","model":"Triple Calendar","style":"dress","caliber":"JLC 484","has_box":null,"winding":"manual","currency":"USD","brand_key":"jaegerlecoultre","condition":null,"reference":"2904","dial_color":null,"has_papers":null,"description":"This is a well preserved 1950s Jaeger-LeCoultre Triple Calendar ref. 2904 in a 35mm steel case featuring a beautiful dial and powered by the manually wound JLC caliber 484.","price_cents":1195000,"case_size_mm":35,"case_material":"steel","complications":["date"]}'::jsonb, '85858b7675a07577fa7562533d2dbe3263117bf5f47ef49da4cb73b7cfd6a6e6', '127127a73fa88c80bdb0e94508f7d824cffea76ad96c52dcd328b5c7b52a1628', '45be467599317508b0950a3fbe326e4e5dc833774d928e2a4e9b9ef607eaa9c3', null, '24307a22-363e-49bf-b341-43216d6918da', '2026-09-14T15:48:11.951285+00:00', '2026-09-22T01:08:52.208+00:00'),
  ('25efe3ca-e1c7-48a0-b6ec-eb08a2c3596a', 'ad0d7d71-741a-4b65-9465-641ed9cc0199', 'squarespace', 'squarespace:678c1f992b47a06ca04ef939', 'https://goldfingersvintage.com/watches/p/1990s-omega-constellation-day-date-lapis-dial-18k-yg', '{"meta":{"sku":"GVW165","vendor":null,"updatedAt":"2026-08-28T19:13:37.955Z","photoCount":11,"productType":null,"publishedAt":"2025-01-18T21:43:32.579Z"},"text":"A fantastic and blingy 1990s Omega Constellation Day-Date in solid 18K yellow gold, with a factory diamond set bezel, oceanic blue lapis lazuli stone dial and integrated flat link bracelet powered by an Omega quartz caliber. \nWho says Omega doesn’t like to party? Well, most people. However this watch proves the contrary. An obvious answer to the question “What if Omega tried to Polo?”. For a fraction of the price I think you can almost out do it’s cousin from the opulent manufacturer Piaget. \nYou’re not going to buy this watch and discuss the movement. It’s a quartz caliber. Ask me if I care? (I don’t). Because this crazy conversation piece is all beauty and no brains. That is the point. \nSized to fit a 6.75 inch wrist. \n 34mm case, which wears large due to the integrated bracelet. \n Lapis dial free of cracks and extra clean.","title":"1990''s Omega Constellation Day-Date Lapis Dial 18K YG","currency":"USD","available":true,"photoUrls":["https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/8f6c1b3d-e793-4afe-a545-7f5f62cc29e0/DSC07153.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/a7f75289-3334-4d78-9fcf-0eda5047c49f/DSC07173.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/91eedfec-cb96-46f7-8e57-9313849809c3/DSC07160.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/6c22cdbe-c59e-4d74-8e6a-abb731044b14/DSC07161.jpg?format=1500w","https://images.squarespace-cdn.com/content/v1/64d53a504f5aee6d2b32ee14/7d1b8a19-5be1-4fd8-93ba-d2ce8a